log.raw:
{
  "understanding": {
    "purpose": "예금·적금 상품의 금리와 가입 조건, 특징을 비교해 적합한 상품을 고르는 표다.",
    "reading": "상품명을 기준으로 각 행을 따라 읽고, 금리·기간·최소 금액을 세로로 비교한 뒤 특징에서 자격과 제한을 확인한다. 특징의 긴 설명이 만드는 행 높이를 다른 셀의 자연스러운 줄바꿈에 활용할 수 있다.",
    "groups": [
      "금리(연)·가입 기간·최소 금액은 상품 간에 반복해서 비교하는 핵심 조건이다.",
      "상품명과 특징은 각각 비교 대상의 식별과 상품별 조건의 해석을 돕는다."
    ],
    "keep_intact": [
      "상품명을 알아보기 쉬운 단위로 유지한다.",
      "금리의 숫자와 퍼센트 기호, 범위 및 우대 금리 수치를 분리하지 않는다.",
      "기간의 숫자와 단위, 금액의 숫자와 통화 단위를 분리하지 않는다."
    ],
    "may_wrap": [
      "특징의 설명은 어절과 문장 단위로 자연스럽게 줄바꿈할 수 있다.",
      "기본 금리와 우대 금리를 연결하는 설명은 수치를 유지하면서 줄바꿈할 수 있다.",
      "여러 가입 기간의 목록은 각 기간을 유지하면서 줄바꿈할 수 있다."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [133, 125, 110, 103, 248],
      "idea": "상품명과 최소 금액을 한 줄로 유지하고 금리와 기간에 적당한 폭을 주면서 특징에 남은 공간을 배분한 균형형이다."
    },
    {
      "name": "B",
      "widths": [125, 160, 140, 103, 191],
      "idea": "금리와 가입 기간의 세로 비교를 우선해 핵심 조건의 줄바꿈을 줄이고, 특징 설명은 더 깊게 감싼다."
    },
    {
      "name": "C",
      "widths": [115, 120, 95, 85, 304],
      "idea": "특징에 가장 넓은 공간을 주고 상품명과 핵심 조건의 일부 줄바꿈을 설명이 만드는 행 높이에 흡수한다."
    }
  ]
}
